import{_ as t,o,c as a,a2 as s}from"./chunks/framework.7R1OEGYz.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Open AgentHub","text":"Coding agents, running in your cluster","tagline":"Start a session, watch it work, approve what it wants to do — from the browser or from your phone.","actions":[{"theme":"brand","text":"Install","link":"/getting-started"},{"theme":"alt","text":"View on GitHub","link":"https://github.com/open-agenthub/open-agenthub"}]},"features":[{"title":"Sessions in Kubernetes","details":"Every session is its own unprivileged pod with its own workspace, network policy, and mounted credentials."},{"title":"Approve from anywhere","details":"Tool-permission prompts reach you in the web app, in Telegram, or in Signal — or skip them entirely with auto approve."},{"title":"Bring your own agent","details":"Claude Code, Codex, Cursor, OpenClaw, and OpenCode, each with subscription or API-key billing, or your own model endpoint."}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1794096555000}'),r={name:"index.md"};function i(n,e,l,d,p,h){return o(),a("div",null,[...e[0]||(e[0]=[s('<h2 id="where-to-start" tabindex="-1">Where to start <a class="header-anchor" href="#where-to-start" aria-label="Permalink to &quot;Where to start&quot;">​</a></h2><p>If you have a cluster, go to <a href="/docs/getting-started">Install</a>. If you are upgrading an existing release, read <a href="/docs/upgrading">Upgrading</a> first — there is one Helm pitfall that bites almost everyone. Setting up an instance for a pilot team? Follow <a href="/docs/pilot-setup">Pilot setup</a>; for help, see <a href="/docs/support">Support</a>.</p><p>New here? The <a href="/docs/features">feature overview</a> lists every feature, its edition and the page that explains it. To learn the daily work, start with <a href="/docs/sessions">Sessions</a>, <a href="/docs/projects">Projects</a>, the <a href="/docs/workspace">Workspace</a> and <a href="/docs/questions-approvals">Questions and approvals</a>.</p><p>The most common setup tasks after installing:</p><ul><li><a href="/docs/chat">Chat integrations</a> — get session updates and approve permissions from your phone.</li><li><a href="/docs/git">Git integrations</a> — let sessions clone and push without a manual token.</li><li><a href="/docs/provider-login">Provider login</a> — sign in to your agent&#39;s provider from a session.</li><li><a href="/docs/local-sessions">Continue locally</a> — take Claude Code or Codex history to your workstation.</li><li><a href="/docs/mcp">MCP clients</a> — connect external clients over HTTP or stdio.</li><li><a href="/docs/auto-approve">Auto approve</a> — let a session run its tools without asking.</li></ul><h2 id="editions" tabindex="-1">Editions <a class="header-anchor" href="#editions" aria-label="Permalink to &quot;Editions&quot;">​</a></h2><p>The core is AGPL-3.0. Enterprise features live under <code>ee/</code> in the repository and need a valid license: session and project sharing, Slack, org-wide usage limits, groups and roles from your identity provider, allowed agent kinds, and sharing MCP servers and skills with others. Telegram and Signal are part of the free core. Without a licence the Enterprise features are switched off and everything else keeps working.</p>',7)])])}const g=t(r,[["render",i]]);export{u as __pageData,g as default};
